  const watch = P.watchPoint(WIN, 176, WORK);
  const ledge = P.ledgePoint(WIN, 176, WORK);
  const circle = P.circlePoint(WIN, 0, 176, WORK, 1);
  const bask = P.baskPoint(WIN, 176, WORK);
