  assert.ok(P.DUR.cover !== Overlay.DUR.wall);
  assert.ok(P.DUR.cover !== Overlay.DUR.flatten);
  assert.ok(P.DUR.cover !== Overlay.DUR.unfurl);
  assert.ok(P.DUR.cover !== Overlay.DUR.circle);
  assert.ok(P.DUR.cover !== Overlay.DUR.draw);
  assert.ok(P.DUR.cover !== Overlay.DUR.fill);
  assert.ok(P.DUR.coverHold !== Overlay.DUR.trailHold);
  assert.ok(P.DUR.coverHold !== Overlay.DUR.puffHold);
  assert.ok(P.DUR.coverHold !== Overlay.DUR.plopHold);
  assert.ok(P.DUR.coverHold !== Overlay.DUR.drawHold);
