  assert.ok(dee.lift > 6, "then she dees once");
  assert.ok(Math.abs(dee.rot) < 12, "a small dee, not Soot's fan");
  const stoop = P.soarPath(0.84);
  assert.ok(dee.lift > stoop.lift + 10, "a dee, not Hook's stoop");
